package com.anthonyal2k.runekitestreak;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("runekitestreak")
public interface RuneKiteStreakConfig extends Config {
	@ConfigItem(keyName = "sourceName", name = "Loot source", position = 0,
			description = "Name of the loot source to watch (as shown in Loot Tracker)")
	default String sourceName() { return "Wilderness Agility Dispenser"; }

	@ConfigItem(keyName = "announceInChat", name = "Announce in chat", position = 1,
			description = "Post streak updates to the game chat")
	default boolean announceInChat() { return true; }
}

package com.anthonyal2k.runekitestreak;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.ItemID;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;

@Slf4j // Added for standard RuneLite logging
@PluginDescriptor(
		name = "Rune Kite Streak",
		description = "Counts consecutive Wildy Agility laps that drop a rune kiteshield",
		tags = {"agility", "wilderness", "loot", "streak"}
)
public class RuneKiteStreakPlugin extends Plugin {

	private static final int TARGET_ITEM_ID = ItemID.RUNE_KITESHIELD;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private RuneKiteStreakConfig config;

	int currentStreak = 0;
	int longestStreak = 0;

	@Provides
	RuneKiteStreakConfig provideConfig(ConfigManager cm) {
		return cm.getConfig(RuneKiteStreakConfig.class);
	}

	@Override
	protected void startUp() throws Exception {
		log.info("Rune Kite Streak started!");
	}

	@Override
	protected void shutDown() throws Exception {
		log.info("Rune Kite Streak stopped!");
		// REQUIRED: Reset your state variables so the plugin shuts down cleanly
		currentStreak = 0;
		longestStreak = 0;
	}

	@Subscribe
	public void onLootReceived(LootReceived event) {
		// Removed null check: Guice guarantees 'config' is injected
		String expectedSource = config.sourceName();
		if (!event.getName().equalsIgnoreCase(expectedSource)) return;

		boolean gotKite = event.getItems().stream()
				.anyMatch(i -> i.getId() == TARGET_ITEM_ID);

		if (gotKite) {
			currentStreak++;
			if (currentStreak > longestStreak) longestStreak = currentStreak;
			announce("Rune kite streak: " + currentStreak + "  (best: " + longestStreak + ")");
		} else {
			if (currentStreak > 0) {
				announce("Streak broken at " + currentStreak + ".  Best still: " + longestStreak);
			}
			currentStreak = 0;
		}
	}

	private void announce(String text) {
		// Removed null checks: Guice guarantees these are injected
		if (!config.announceInChat()) return;

		String msg = new ChatMessageBuilder().append(text).build();
		chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(msg)
				.build());
	}
}

package com.anthonyal2k.runekitestreak;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RuneKiteStreakPlugin.class);
		RuneLite.main(args);
	}
}

package com.anthonyal2k.runekitestreak;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import net.runelite.api.ItemID;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

// 1. Tell JUnit to use Mockito
@RunWith(MockitoJUnitRunner.class)
public class StreakLogicTest {

    // 2. Create a mock version of your config
    @Mock
    private RuneKiteStreakConfig config;

    // 3. Inject the mock directly into the plugin, replacing the "new" keyword
    @InjectMocks
    private RuneKiteStreakPlugin plugin;

    @Before
    public void setup() {
        // 4. Define exactly what the mock config should return when the plugin asks for it
        when(config.sourceName()).thenReturn("Wilderness Agility Dispenser");

        // We set this to false so the plugin doesn't try to use the missing ChatMessageManager
        when(config.announceInChat()).thenReturn(false);
    }

    private LootReceived lap(int... itemIds) {
        List<ItemStack> items = Arrays.stream(itemIds)
                .mapToObj(id -> new ItemStack(id, 1))
                .collect(java.util.stream.Collectors.toList());
        return new LootReceived("Wilderness Agility Dispenser", 0, LootRecordType.EVENT, items, 1, null);
    }

    @Test
    public void kiteDropsIncrementStreak() {
        plugin.onLootReceived(lap(ItemID.RUNE_KITESHIELD, ItemID.COAL));
        plugin.onLootReceived(lap(ItemID.RUNE_KITESHIELD));
        plugin.onLootReceived(lap(ItemID.RUNE_KITESHIELD, ItemID.MAGIC_LOGS));
        assertEquals(3, plugin.currentStreak);
        assertEquals(3, plugin.longestStreak);
    }

    @Test
    public void nonKiteLapBreaksStreak() {
        plugin.onLootReceived(lap(ItemID.RUNE_KITESHIELD));
        plugin.onLootReceived(lap(ItemID.RUNE_KITESHIELD));
        plugin.onLootReceived(lap(ItemID.COAL, ItemID.MAGIC_LOGS)); // no kite
        assertEquals(0, plugin.currentStreak);
        assertEquals(2, plugin.longestStreak); // best preserved
    }

    @Test
    public void wrongSourceIgnored() {
        LootReceived fromMonster = new LootReceived(
                "Some Other Source", 0, LootRecordType.EVENT,
                Collections.singletonList(new ItemStack(ItemID.RUNE_KITESHIELD, 1)), 1, null);
        plugin.onLootReceived(fromMonster);
        assertEquals(0, plugin.currentStreak);
    }
}
